{
  "groups": [
    {
      "group_id": "low_rate_lockin",
      "rule": "rate_type == 'fixed' and origination_year >= 2020 and origination_year <= 2021",
      "rationale": "These borrowers secured historic low rates and will face significant payment shock at renewal, making them prime candidates for proactive retention."
    },
    {
      "group_id": "stressed_variable_rate",
      "rule": "rate_type == 'variable' and credit_score_band != '720_plus'",
      "rationale": "Variable rate borrowers with sub-optimal credit have absorbed multiple interest rate hikes and face immediate liquidity constraints."
    },
    {
      "group_id": "high_debt_young_family",
      "rule": "n_children >= 2 and household_income_cad < 100000",
      "rationale": "Families with multiple children and moderate income have low discretionary spending and are highly sensitive to rising household costs."
    },
    {
      "group_id": "prime_uninsured_equity",
      "rule": "insured_flag == False and credit_score_band == '720_plus'",
      "rationale": "High-credit uninsured borrowers have the most market options and are the most likely to shop around for better rates at renewal."
    },
    {
      "group_id": "vulnerable_low_credit",
      "rule": "credit_score_band == 'below_600' or credit_score_band == '600_659'",
      "rationale": "Borrowers with lower credit scores have limited refinancing options, effectively making them a captive segment for the existing lender."
    },
    {
      "group_id": "early_tenure_digital",
      "rule": "td_tenure_months <= 36 and channel == 'digital'",
      "rationale": "Newer, digitally-engaged borrowers often lack a strong personal relationship with an advisor, making them more likely to switch lenders online."
    },
    {
      "group_id": "senior_retired_stability",
      "rule": "employment_status == 'retired'",
      "rationale": "Retired borrowers generally have fixed income sources and lower risk appetite, typically preferring to stay with their current institution for simplicity."
    }
  ]
}
